insert into vocabulary_words (word, pronunciation, part_of_speech, plain_meaning, usage_example, etymology, common_mistakes, related_words, conversation_examples, source_article_id)
values ('stuck', 'stuhk', 'adjective', 'unable to move or make progress; feeling trapped in a situation', 'She felt stuck between who she was and who she wanted to be.', 'Old English stician, to pierce or remain fixed.', 'Not the same as lazy - stuck means you want to move but cannot find the direction.', array['trapped','paralyzed','blocked'], array['I have been stuck on this decision for weeks.'], (select id from articles where slug = 'feeling-stuck-going-nowhere'))
on conflict (word) do update set pronunciation = excluded.pronunciation, common_mistakes = excluded.common_mistakes, source_article_id = excluded.source_article_id, updated_at = now();

